contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 loanID_, address to_, address caller_) public {
        // Setup: give the loan an approval entry that may or may not match caller_.
        // First we need some loan to exist; but for a general rule about transferOwnership,
        // we can use any loanID. However, approveTransfer requires msg.sender == loans[loanID].lender,
        // and this contract is msg.sender for all calls.  Since no loan exists yet, calling approveTransfer
        // for an arbitrary loanID will revert (loans[loanID] is zero-initialized, lender=address(0) != msg.sender).
        // To create a loan we would need a full flow.  Instead, we can test the reversion case:
        // For any loanID, if approvals(loanID) != msg.sender, transferOwnership must revert.
        // But the contract may have a loan where the lender is this contract; then we need a matching approval.
        // We cannot create that loan easily.
        // However, the rule we assert is about the relationship between approvals(loanID) and
        // the success of transferOwnership.  Since we can only observe approveTransfer's effect through
        // approvals(loanID), and transferOwnership checks msg.sender == approvals[loanID_].
        // With msg.sender = address(this) for all calls, we can only have approval equal to address(this)
        // if we can call approveTransfer, which requires being the lender of the loan.
        // To get a loan with lender = address(this), we need to clear a request, but that requires
        // a request to exist and debt tokens.  This is too complex for this test.
        //
        // Alternative: directly test the failure condition for arbitrary loanID where no approval is set.
        // Since the contract is fresh, approvals(loanID_) == address(0) != address(this), so transferOwnership
        // should revert.  We can assert that it reverts.  But that's just one case; the general rule
        // is that it reverts iff msg.sender != approvals[loanID_].
        // We can read c.approvals(loanID_) and compare with address(this) to decide whether it should revert.
        // However, we cannot set approvals to address(this) without the setup above.
        // So the rule becomes: transferOwnership reverts exactly when approvals(loanID_) != msg.sender.
        // Since msg.sender is fixed to this contract, we can read the approval and predict.
        address expectedApprover = c.approvals(loanID_); if (__ESBMC_reverted()) return;
        bool shouldRevert = (expectedApprover != address(this));
        bool reverted;
        c.transferOwnership(loanID_); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted == shouldRevert);
    }

    receive() external payable {}
}

