pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 loanID_, address to_, address caller_) internal {
        address expectedApprover;
        try c.approvals(loanID_) returns (address __r) { expectedApprover = __r; } catch { return; }
        bool shouldRevert = (expectedApprover != address(this));
        bool reverted;
        try c.transferOwnership(loanID_) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == shouldRevert);
    }

    function testFuzz_run(uint256 loanID_, address to_, address caller_) public {
        vm.assume(to_.code.length == 0 && uint160(to_) > 0xffff && to_ != address(this) && to_ != address(c) && to_ != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to_ != 0x000000000000000000636F6e736F6c652e6c6f67 && to_ != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to_ != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(caller_.code.length == 0 && uint160(caller_) > 0xffff && caller_ != address(this) && caller_ != address(c) && caller_ != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller_ != 0x000000000000000000636F6e736F6c652e6c6f67 && caller_ != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller_ != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(loanID_, to_, caller_);
    }

    receive() external payable {}
}
